window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5c6165196ac41b55"]={"versions": [{"id": "FIG-5c6165196ac41b55", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Beziehungen zwischen AUTOSAR-Software-Komponenten und Verhaltensmodellen (Behavior Modeling). Es beschreibt den statischen strukturellen Kontext für den Import von AUTOSAR-Komponententypen, Ports und Kalibriergrößen in ein verhaltensmodellierendes Subsystem (<code>BM Software-Component</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Kernentitäten:</p>\n<ul class=\"fig-list\"><li><code>Components::ComponentType</code> (spezialisiert <code>ARElement</code>): Basisklasse für AUTOSAR-Komponententypen. Steht über eine Kompositionsbeziehung (<code>+component</code> / <code>+ports</code>, Multiplizität <code>0..*</code>) zu <code>Components::PortPrototype</code>.\n</li><li><code>Components::PortPrototype</code> (spezialisiert <code>ExistenceDependsOnProperty</code>, <code>Identifiable</code>, <code>PropertyEvaluator</code>): Abstrakte Basisklasse für Port-Prototypen, spezialisiert in <code>Components::PPortPrototype</code> (Provide-Port) und <code>Components::RPortPrototype</code> (Require-Port).\n</li><li><code>Components::AtomicSoftwareComponentType</code>: Spezialisiert <code>Components::ComponentType</code> und aggregiert über die Komposition <code>+characteristics</code> (Kardinalität <code>0..*</code>) Instanzen von <code>Components::Characteristic</code> (spezialisiert <code>DataPrototype</code>).\n</li><li><code>BM Software-Component</code> (aus Package <code>Behavior Modeling</code>): Modellierungsentität, die über gerichtete Abhängigkeiten (<code>«import»</code>) <code>ComponentType</code>, <code>AtomicSoftwareComponentType</code>, <code>PortPrototype</code>, <code>PPortPrototype</code>, <code>RPortPrototype</code> sowie <code>Characteristic</code> importiert bzw. referenziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Struktur- und Metamodell-Diagramm enthält die Darstellung keine dynamischen Interaktionen, zeitlichen Abläufe oder Nachrichtensequenzen. Die gerichteten Abhängigkeiten (<code>«import»</code>) repräsentieren den statischen Modellimport bzw. die Zuordnung von AUTOSAR-Metamodellelementen in die Domäne der Verhaltensmodellierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Abbildung von AUTOSAR Classic-Software-Komponentenstrukturen in Verhaltensmodellierungsumgebungen:</p>\n<ul class=\"fig-list\"><li>Ein Verhaltensmodell-Artefakt (<code>BM Software-Component</code>) bildet einen <code>AtomicSoftwareComponentType</code> ab.\n</li><li>Sämtliche Interaktionspunkte müssen über typisierte Ports (<code>PPortPrototype</code> bzw. <code>RPortPrototype</code>) modelliert werden, die der Komponente aggregiert zugeordnet sind.\n</li><li>Kalibrier- und Kennwerte werden als <code>Characteristic</code> (<code>DataPrototype</code>) aggregiert am atomaren Komponententyp geführt und für das Verhaltensmodell bereitgestellt.\n</li></ul>"}, {"id": "FIG-114052b395ae87ce", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Beziehungen zwischen AUTOSAR-Software-Komponenten und Verhaltensmodellen (Behavior Modeling). Es beschreibt den statischen strukturellen Kontext für den Import von AUTOSAR-Komponententypen, Ports und Kalibriergrößen in ein verhaltensmodellierendes Subsystem (<code>BM Software-Component</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Kernentitäten:</p>\n<ul class=\"fig-list\"><li><code>Components::ComponentType</code> (spezialisiert <code>ARElement</code>): Basisklasse für AUTOSAR-Komponententypen. Steht über eine Kompositionsbeziehung (<code>+component</code> / <code>+ports</code>, Multiplizität <code>0..*</code>) zu <code>Components::PortPrototype</code>.\n</li><li><code>Components::PortPrototype</code> (spezialisiert <code>ExistenceDependsOnProperty</code>, <code>Identifiable</code>, <code>PropertyEvaluator</code>): Abstrakte Basisklasse für Port-Prototypen, spezialisiert in <code>Components::PPortPrototype</code> (Provide-Port) und <code>Components::RPortPrototype</code> (Require-Port).\n</li><li><code>Components::AtomicSoftwareComponentType</code>: Spezialisiert <code>Components::ComponentType</code> und aggregiert über die Komposition <code>+characteristics</code> (Kardinalität <code>0..*</code>) Instanzen von <code>Components::Characteristic</code> (spezialisiert <code>DataPrototype</code>).\n</li><li><code>BM Software-Component</code> (aus Package <code>Behavior Modeling</code>): Modellierungsentität, die über gerichtete Abhängigkeiten (<code>«import»</code>) <code>ComponentType</code>, <code>AtomicSoftwareComponentType</code>, <code>PortPrototype</code>, <code>PPortPrototype</code>, <code>RPortPrototype</code> sowie <code>Characteristic</code> importiert bzw. referenziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Struktur- und Metamodell-Diagramm enthält die Darstellung keine dynamischen Interaktionen, zeitlichen Abläufe oder Nachrichtensequenzen. Die gerichteten Abhängigkeiten (<code>«import»</code>) repräsentieren den statischen Modellimport bzw. die Zuordnung von AUTOSAR-Metamodellelementen in die Domäne der Verhaltensmodellierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Abbildung von AUTOSAR Classic-Software-Komponentenstrukturen in Verhaltensmodellierungsumgebungen:</p>\n<ul class=\"fig-list\"><li>Ein Verhaltensmodell-Artefakt (<code>BM Software-Component</code>) bildet einen <code>AtomicSoftwareComponentType</code> ab.\n</li><li>Sämtliche Interaktionspunkte müssen über typisierte Ports (<code>PPortPrototype</code> bzw. <code>RPortPrototype</code>) modelliert werden, die der Komponente aggregiert zugeordnet sind.\n</li><li>Kalibrier- und Kennwerte werden als <code>Characteristic</code> (<code>DataPrototype</code>) aggregiert am atomaren Komponententyp geführt und für das Verhaltensmodell bereitgestellt.\n</li></ul>"}], "trans": [{"from": "FIG-5c6165196ac41b55", "to": "FIG-114052b395ae87ce", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
